import Foundation
import AppKit
import DuoPasteCore

/// 已知的"非用户原始操作"类型，应跳过。
/// 参考 nspasteboard.org 约定 + Apple 自家的 transient 标记。
private let skipMarkerTypes: Set<String> = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",          // 1Password 的私有标记
    "Pasteboard generator type",          // 老式应用偶尔用
]

/// 调用 tick 之前在 main actor 上 snapshot 一下 frontApp——NSWorkspace.frontmostApplication
/// 是 UI 状态,后台读不保证准。frontApp 信息只在 main 短一瞥(几个属性 + pid),不卡。
private struct FrontAppSnapshot: Sendable {
    let bundleID: String?
    let localizedName: String?
    let pid: pid_t?
}

/// 后台 actor 轮询 NSPasteboard。原本是 @MainActor + RunLoop.main Timer——macOS Universal
/// Clipboard 同步卡住时 pasteboardd IPC 阻塞 main thread,搜索框 / 状态栏 / hotkey 一起冻。
/// 改 actor 后所有 NSPasteboard 同步调用都跑在 actor 自家 executor 上,main 不再被牵连。
public actor PasteboardWatcher {
    public typealias Callback = @MainActor @Sendable (CapturedPasteboard) -> Void

    /// NSPasteboard 单例 thread-safe（pasteboardd IPC client 内部加锁）。
    /// actor 后台读 + main 写都通过同一进程内代理,无并发问题。
    /// nonisolated(unsafe) 让 actor 外（barrier 拿来给 @MainActor 写回）也能引用同一实例。
    nonisolated(unsafe) private let pasteboard: NSPasteboard
    private let pollInterval: TimeInterval
    /// debounce 窗口（纳秒）。changeCount 跳变后等这么久没新跳变才真正 capture。
    ///
    /// 用途：合并 app 自己的连续多次剪贴板写入。已知场景：
    /// - **CleanShot**：截图保存时先写本地缓存路径，iCloud Drive 同步完成后改写
    ///   iCloud 路径——一次截图两次 changeCount 跳变，原本会变成两条 file item
    /// - 富文本 app（Notes / Mail）在写 .rtf + .html + .string 时可能分多次 setString
    ///
    /// 0 = 关闭 debounce 立即 capture（测试 / 调试注入）。默认 500ms：
    /// - 远低于人眼反应（200-300ms）+ panel 打开动画时间，用户完全察觉不到
    /// - 比 CleanShot 观察到的 iCloud 同步延迟（~200ms）留充足 buffer
    private let debounceNs: Int64
    private var lastChangeCount: Int
    /// 进入 debounce 等待时记录的触发时刻。0 = 当前没 pending capture。
    /// 每次 changeCount 跳变都重置为 `now + debounceNs`，直到稳定一整个窗口才触发
    private var pendingDeadlineNs: Int64 = 0
    /// 最近一次 cc 跳变那一刻的 frontApp。每次新跳变 main hop 一次刷新，capture 时直接
    /// 消费而**不**再 hop——避免"cc 跳变 → debounce 等 500ms → 用户 ⌘Tab 切走 → capture
    /// 用了新 app 的 frontmost"导致 source_app 列脏。
    /// nil = 没 pending capture（pendingDeadlineNs == 0 时同步成 nil）
    private var pendingFrontApp: FrontAppSnapshot?
    /// pollLoop 跑在自己的 Task 里;start/stop 跟 cancel 它配对
    private var pollTask: Task<Void, Never>?
    /// barrier 在跑——`pasteBack` 期间 await MainActor.run 会释放 actor isolation,
    /// 让别的 actor 方法插入。tick 看到这个 flag 直接 return 跳过那一拍,
    /// 防止 self-write 的 changeCount 跳变被并发 tick 当成新 capture
    private var isPasteBackInFlight: Bool = false
    private let onCapture: Callback
    /// 仅 RTF 路径用于解码前 raw-size 守门，避免 50MB RTF source 被 NSAttributedString 同步
    /// 解析后才走到 CaptureService 的 text byte cap。raw RTF 字节 > 该上限时跳过 decode，
    /// 把 raw RTF 直接作为兜底 .rtf 文本返回 —— CaptureService 后续 byte-cap 会拦下。
    /// 默认值匹配 Config.CaptureLimits.maxTextBytes 默认（512 * 1024）；AppDelegate 注入实际配置。
    private let maxRawRTFBytes: Int
    /// file URL 分支：图片类型文件的字节上限。超限只记路径字符串，不读字节。
    /// 默认值匹配 Config.CaptureLimits.maxBlobBytes 默认（32 MB）；AppDelegate 注入实际配置。
    private let maxBlobBytes: Int

    public init(
        pasteboard: NSPasteboard = .general,
        pollInterval: TimeInterval = 0.2,
        debounceMs: Int = 500,
        maxRawRTFBytes: Int = 512 * 1024,
        maxBlobBytes: Int = 32 * 1024 * 1024,
        onCapture: @escaping Callback
    ) {
        self.pasteboard = pasteboard
        self.pollInterval = pollInterval
        self.debounceNs = Int64(max(0, debounceMs)) * 1_000_000
        self.maxRawRTFBytes = maxRawRTFBytes
        self.maxBlobBytes = maxBlobBytes
        self.lastChangeCount = pasteboard.changeCount
        self.onCapture = onCapture
    }

    public func start() {
        guard pollTask == nil else { return }
        pollTask = Task { [weak self] in
            await self?.pollLoop()
        }
    }

    public func stop() {
        pollTask?.cancel()
        pollTask = nil
    }

    /// 唯一对外的 paste-back 入口。actor 串行保证 flush → main 写回 → suppress
    /// 三步之间不会被并发的 polling tick 插入。
    /// `write` 闭包跑在 @MainActor 上(NSPasteboard 写入习惯让 main 做),返回值原样透传给调用方
    public func pasteBack<R: Sendable>(
        _ write: @MainActor @Sendable () -> R
    ) async -> R {
        isPasteBackInFlight = true
        defer { isPasteBackInFlight = false }

        // 1. flush:窗口内 pending 的真实复制 / tick 未观察到的跳变都先 capture,
        //    防 step 2 的 pb 覆写把用户的复制吞掉
        await flushPendingIfAny()

        // 2. hop main 同步写 pasteboard——actor isolation 释放,但 isPasteBackInFlight=true
        //    让 tick 跳过这一拍。Copyback 内部全是同步的 setData/writeObjects
        let result = await MainActor.run { write() }

        // 3. suppress:把 lastChangeCount 推到当前 cc,下次 tick 看到不变 → 跳过
        suppressUpToCurrent()

        return result
    }

    /// 内部 fast-path:把当前 pb.changeCount 推给 lastChangeCount,清空 pending,
    /// 让后续 tick 不把 self-write 那次跳变当成新 capture
    private func suppressUpToCurrent() {
        lastChangeCount = pasteboard.changeCount
        pendingDeadlineNs = 0
        pendingFrontApp = nil
    }

    /// 内部 flush:若 debounce 窗口里有 pending 的真实复制 (`pendingDeadlineNs > 0`)
    /// 或两次 tick 间用户刚复制完(`pasteboard.changeCount != lastChangeCount`),
    /// 立刻 capture 一次。没有任何变化 → no-op。
    /// pasteBack barrier 调用,完成后才让 main 写 pb 覆盖。
    private func flushPendingIfAny() async {
        let cc = pasteboard.changeCount
        if cc != lastChangeCount {
            lastChangeCount = cc
            pendingDeadlineNs = 0
            // 临门一脚的真实复制——同步 hop 一次拿 frontApp,绑定到这次 capture
            let frontApp = await MainActor.run { Self.snapshotFrontApp() }
            pendingFrontApp = frontApp
            await capture()
            return
        }
        guard pendingDeadlineNs > 0 else { return }
        pendingDeadlineNs = 0
        await capture()
    }

    private func pollLoop() async {
        let intervalNs = UInt64(max(0.01, pollInterval) * 1_000_000_000)
        while !Task.isCancelled {
            try? await Task.sleep(nanoseconds: intervalNs)
            if Task.isCancelled { return }
            await tick()
        }
    }

    private func tick() async {
        // pasteBack 正在 main hop——self-write 那次 cc 跳变不要被这一拍当成 capture
        if isPasteBackInFlight { return }

        let cc = pasteboard.changeCount  // ← UC pending 时这里在 actor 后台阻塞,main 不受影响
        if cc != lastChangeCount {
            lastChangeCount = cc
            // 关键时机:cc 跳变的那一拍 main hop 拿 frontApp,绑定到这次 capture。
            // 不能等到 capture() 内部 hop——debounce 500ms 期间用户可能 ⌘Tab 切走,
            // 那时 frontmostApplication 已是另一个 app,source_app 列就写错了
            let frontApp = await MainActor.run { Self.snapshotFrontApp() }
            pendingFrontApp = frontApp
            if debounceNs > 0 {
                pendingDeadlineNs = Clock.nowNs() + debounceNs
                return
            }
            await capture()
            return
        }
        guard pendingDeadlineNs > 0,
              Clock.nowNs() >= pendingDeadlineNs
        else { return }
        pendingDeadlineNs = 0
        await capture()
    }

    /// 真正读 pasteboard 提取内容并回调。从 tick() 拆出来——debounce 路径在 deadline
    /// 到期时调；零 debounce 路径在 changeCount 跳变时立刻调。
    /// 注意：skipMarkerTypes 检测放在这里（不是 changeCount 跳变时刻），因为
    /// debounce 窗口内 app 可能还没写完所有 type marker
    private func capture() async {
        let capturedAtNs = Clock.nowNs()

        // 跳过特殊标记类型
        if let types = pasteboard.types {
            for t in types where skipMarkerTypes.contains(t.rawValue) {
                pendingFrontApp = nil
                return
            }
        }

        // frontApp 是 cc 跳变那一刻 main hop 拿到的 snapshot;capture 直接消费,
        // 不再额外 hop——避免 debounce 期间 frontmost 切走导致 source_app 错挂。
        // pending 异常路径（tick 看到 cc==lastCount + deadline 到期）frontApp 为 nil,
        // extract 仍能继续(只是 bundle/name 列空)
        let frontApp = pendingFrontApp ?? FrontAppSnapshot(bundleID: nil, localizedName: nil, pid: nil)
        pendingFrontApp = nil

        guard let captured = extract(capturedAtNs: capturedAtNs, frontApp: frontApp) else {
            return
        }
        // 诊断:可疑 capture 把 NSPasteboard types 全打出来(短文本/RTF/HTML 三类)。
        // 用途:识别漏配的 type marker(应进 skipMarkerTypes),或定位 frontmost 时序错位
        let shouldLog: Bool
        if let t = captured.text, t.count <= 8, captured.kind == .text {
            shouldLog = true
        } else if captured.kind == .rtf {
            shouldLog = true
        } else if captured.kind == .html {
            shouldLog = true
        } else {
            shouldLog = false
        }
        if shouldLog {
            let types = pasteboard.types?.map(\.rawValue).joined(separator: ",") ?? "(nil)"
            let textLen = captured.text?.count ?? 0
            let prevSlice = (captured.text ?? "").prefix(40)
            fputs("capture suspect kind=\(captured.kind.rawValue) bundle=\(captured.sourceAppBundleID ?? "?") name=\(captured.sourceAppName ?? "?") len=\(textLen) types=[\(types)] preview=\(String(prevSlice).debugDescription)\n", stderr)
        }
        // hop 回 main 投递给 handleCapture——onCapture 是 @MainActor callback
        let payload = captured
        let cb = onCapture
        await MainActor.run { cb(payload) }
    }

    @MainActor
    private static func snapshotFrontApp() -> FrontAppSnapshot {
        let app = NSWorkspace.shared.frontmostApplication
        return FrontAppSnapshot(
            bundleID: app?.bundleIdentifier,
            localizedName: app?.localizedName,
            pid: app?.processIdentifier
        )
    }

    /// self-pid 过滤谓词:抽成 static 便于单测,详见 extract() 顶端注释
    public static func shouldSkipFrontApp(pid: pid_t?, selfPid: pid_t) -> Bool {
        guard let pid else { return false }
        return pid == selfPid
    }

    private func extract(capturedAtNs: Int64, frontApp: FrontAppSnapshot) -> CapturedPasteboard? {
        // self-pid 过滤(双层防御之一):duo-paste 自己 frontmost 时直接 return nil。
        //
        // 为什么必须留：pasteBack 路径的 suppressUpToCurrent 只挡程序化写回(自动 paste 后
        // 把 lastChangeCount 推到当前 cc),挡不住用户在搜索框 / Settings 文本框里手动
        // Cmd+C——那次 changeCount 真实自增,suppressUpToCurrent 来不及调用,结果会把
        // duo-paste 自家 UI 的复制重新入库,触发 search Cmd+C → 入库 → 又出现在结果里的
        // 反复回环。pasteBack 的程序化 barrier 是第一层防御,self-pid 过滤是第二层。
        //
        // 副作用(已知接受):self frontmost 期间所有 changeCount 自增都被吃掉,nextTick
        // cc != lastChangeCount 但被这里 return nil 拦掉,直到 user 切到别的 app。这是
        // 期望行为——剪贴板管理器自己 UI 里的复制不该污染历史。
        if Self.shouldSkipFrontApp(pid: frontApp.pid, selfPid: ProcessInfo.processInfo.processIdentifier) {
            return nil
        }
        let bundleID = frontApp.bundleID
        let appName = frontApp.localizedName

        // 1) 文件 URL
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [
            .urlReadingFileURLsOnly: true
        ]) as? [URL], !urls.isEmpty {
            let paths = urls.map { $0.path }.joined(separator: "\n")

            // 单文件且后缀是图片：尝试读字节存 blob，让 mirror client 能通过 /blob/<sha> 同步
            var imageBlob: Data? = nil
            var imageBlobExt: String? = nil
            var imageBlobMime: String? = nil
            if urls.count == 1 {
                let url = urls[0]
                if fileLooksLikeImage(path: url.path) {
                    // 先检查文件大小，避免在 @MainActor 路径上同步读超大文件
                    let fileSize = (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize ?? 0
                    if fileSize > 0 && fileSize <= maxBlobBytes {
                        // 读失败（权限/文件已删）→ imageBlob=nil，静默降级为纯路径 capture
                        imageBlob = try? Data(contentsOf: url)
                        if imageBlob != nil {
                            let ext = url.pathExtension.lowercased()
                            imageBlobExt = ext
                            imageBlobMime = Self.imageExtToMime(ext)
                        }
                    }
                }
            }

            return CapturedPasteboard(
                kind: .file,
                text: paths,
                blob: imageBlob,
                blobExt: imageBlobExt,
                blobMime: imageBlobMime,
                fileName: urls.count == 1 ? urls[0].lastPathComponent : nil,
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }

        // 2) 图片：优先 PNG，再 TIFF
        if let data = pasteboard.data(forType: .png) {
            return CapturedPasteboard(
                kind: .image,
                blob: data,
                blobExt: "png",
                blobMime: "image/png",
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }
        if let data = pasteboard.data(forType: .tiff) {
            return CapturedPasteboard(
                kind: .image,
                blob: data,
                blobExt: "tiff",
                blobMime: "image/tiff",
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }

        // 3) RTF
        if let rtf = pasteboard.string(forType: .rtf) {
            // RTF 降级：剪贴板历史里展示 `{\rtf1\ansi\ansicpg... \cocoartf...}` 这种 raw
            // markup 完全没意义——搜索命中不了、preview 噪声大、bundle name 也只是 host
            // app（Codex/Claude Desktop/Notes/Mail 等）。代价：失去"按原样 paste 回带样
            // 式"——但本仓库定位是剪贴板历史检索，不是富文本中转站；况且 Copyback 已经
            // 在多数情况下双写 rtf+string，对端粘贴体验由对端 app 决定。
            //
            // 三层降级：
            // (a) pasteboard 自己写了 .string → 直接用
            // (b) 只写了 .rtf（Notes/Mail 部分场景）→ 本地解 RTF markup 拿 attributed.string
            // (c) 解析失败/全空白/raw 太大 → 才存 raw rtf 当兜底（CaptureService 字节守门后续拦下）
            //
            // (a)/(b) 拿到 plain 后走 plainTextOrURL —— 浏览器把 URL 选中文本同时塞 .rtf + .string
            // 时不能落到 .text 兜底（chip "链接" 会漏计），跟 step 6 用同一份 looksLikeURL 判断
            if let plain = pasteboard.string(forType: .string),
               !plain.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            {
                return Self.plainTextOrURL(
                    plain,
                    sourceAppBundleID: bundleID,
                    sourceAppName: appName,
                    capturedAtNs: capturedAtNs
                )
            }
            // raw RTF 已经超过 text cap → 跳过 NSAttributedString 解析，避免在 @MainActor
            // 轮询路径上同步分配巨大 attributed string。decoded plain ≤ raw rtf，所以这种 case
            // 解出来也大概率仍超 cap，让 CaptureService 拦 raw 即可
            if rtf.utf8.count <= maxRawRTFBytes,
               let plain = Self.decodeRTFToPlain(rtf),
               !plain.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            {
                return Self.plainTextOrURL(
                    plain,
                    sourceAppBundleID: bundleID,
                    sourceAppName: appName,
                    capturedAtNs: capturedAtNs
                )
            }
            return CapturedPasteboard(
                kind: .rtf,
                text: rtf,
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }

        // 4) HTML
        if let html = pasteboard.string(forType: .html) {
            // web view selection 降级：WebKit / Chromium 系（浏览器 + Electron + Codex /
            // ChatGPT / Claude Desktop / DingTalk 等）写 HTML 时前面会塞
            // <meta charset='utf-8'>（裸前缀或 <head> 包裹两种变体，DingTalk 走后者），
            // 内容是带 inline style + data-* 属性的一坨 markup——对剪贴板管理器毫无用处。
            // 此时如果 .string 也有非空 plain text，优先用 plain，丢 markup。
            if looksLikeWebViewHTML(html),
               let plain = pasteboard.string(forType: .string),
               !plain.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            {
                // 同 RTF 降级：浏览器/Electron 选中 URL 文本会同时写 HTML + .string，
                // plain 落 .text 会让 chip "链接" 漏计；走同一份 looksLikeURL 判断
                return Self.plainTextOrURL(
                    plain,
                    sourceAppBundleID: bundleID,
                    sourceAppName: appName,
                    capturedAtNs: capturedAtNs
                )
            }
            return CapturedPasteboard(
                kind: .html,
                text: html,
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }

        // 5) URL（web URL，区别于 fileURL）
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self]) as? [URL],
           let url = urls.first, !url.isFileURL
        {
            return CapturedPasteboard(
                kind: .url,
                text: url.absoluteString,
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }

        // 6) 纯文本——trim 后判空，过滤掉单空格 / 纯换行 / 纯 tab 之类的伪复制。
        // 实测来源：Zed Vim mode 在空白字符上 yank、LSP 命令副作用、空选择 Cmd+C 等。
        // 不直接 .isEmpty 判断会让这些 1-字节空白条目刷进列表（preview 完全空，无信息量）。
        if let s = pasteboard.string(forType: .string),
           !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return Self.plainTextOrURL(
                s,
                sourceAppBundleID: bundleID,
                sourceAppName: appName,
                capturedAtNs: capturedAtNs
            )
        }

        return nil
    }

    /// 把一段已确认非空的 plain text 包成 CapturedPasteboard。trim 后符合 `looksLikeURL`
    /// 升 `.url`，否则保留原 `.text`。RTF/HTML 降级 + step 6 都共用，让"plain text + 看
    /// 起来是 URL → 升 .url" 这条契约只在一处实现，避免 step 6 走过升级、降级路径漏判
    /// 导致 chip "链接" 计数三条路径口径分裂
    private static func plainTextOrURL(
        _ s: String,
        sourceAppBundleID: String?,
        sourceAppName: String?,
        capturedAtNs: Int64
    ) -> CapturedPasteboard {
        let trimmed = s.trimmingCharacters(in: .whitespacesAndNewlines)
        if looksLikeURL(trimmed) {
            return CapturedPasteboard(
                kind: .url,
                text: trimmed,
                sourceAppBundleID: sourceAppBundleID,
                sourceAppName: sourceAppName,
                capturedAtNs: capturedAtNs
            )
        }
        return CapturedPasteboard(
            kind: .text,
            text: s,
            sourceAppBundleID: sourceAppBundleID,
            sourceAppName: sourceAppName,
            capturedAtNs: capturedAtNs
        )
    }

    /// 用 NSAttributedString 把 RTF source 解成纯文本。失败返回 nil，调用方走兜底。
    private static func decodeRTFToPlain(_ rtf: String) -> String? {
        guard let data = rtf.data(using: .utf8),
              let attr = try? NSAttributedString(
                data: data,
                options: [.documentType: NSAttributedString.DocumentType.rtf],
                documentAttributes: nil
              )
        else { return nil }
        return attr.string
    }

    /// 图片文件后缀 → MIME type。未知格式返回通用二进制流类型。
    private static func imageExtToMime(_ ext: String) -> String {
        switch ext {
        case "png":        return "image/png"
        case "jpg", "jpeg": return "image/jpeg"
        case "heic":       return "image/heic"
        case "heif":       return "image/heif"
        case "gif":        return "image/gif"
        case "webp":       return "image/webp"
        case "tiff", "tif": return "image/tiff"
        case "bmp":        return "image/bmp"
        default:           return "application/octet-stream"
        }
    }
}
